277	impl VersionlessPackageSpec {
278	    /// Fill in the `version` to get a complete [`PackageSpec`].
279	    pub fn at(self, version: PackageVersion) -> PackageSpec {
280	        PackageSpec {
281	            namespace: self.namespace,
282	            name: self.name,
283	            version,
284	        }
285	    }
286	}
